import math
from numbers import Real


def line_bounds(words):
    if not isinstance(words, list):
        raise TypeError("words must be a list")
    required = {"line", "text", "x0", "y0", "x1", "y1"}
    groups = {}

    for word in words:
        if not isinstance(word, dict):
            raise TypeError("each word must be a dictionary")
        if set(word) != required:
            raise ValueError("word keys are invalid")
        line = word["line"]
        if isinstance(line, bool) or not isinstance(line, int):
            raise TypeError("line must be an integer")
        if not isinstance(word["text"], str):
            raise TypeError("text must be a string")

        coords = []
        for name in ("x0", "y0", "x1", "y1"):
            value = word[name]
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError(f"{name} must be real")
            if not math.isfinite(value):
                raise ValueError(f"{name} must be finite")
            coords.append(float(value))
        x0, y0, x1, y1 = coords
        if x0 > x1 or y0 > y1:
            raise ValueError("coordinates are reversed")

        if line not in groups:
            groups[line] = {
                "line": line,
                "parts": [word["text"]],
                "x0": x0,
                "y0": y0,
                "x1": x1,
                "y1": y1,
            }
        else:
            group = groups[line]
            group["parts"].append(word["text"])
            group["x0"] = min(group["x0"], x0)
            group["y0"] = min(group["y0"], y0)
            group["x1"] = max(group["x1"], x1)
            group["y1"] = min(group["y1"], y1)

    return [
        {
            "line": line,
            "text": " ".join(groups[line]["parts"]),
            "x0": groups[line]["x0"],
            "y0": groups[line]["y0"],
            "x1": groups[line]["x1"],
            "y1": groups[line]["y1"],
        }
        for line in sorted(groups)
    ]
