import math
import unittest
from fractions import Fraction

from solution import line_bounds


class LineBoundsTests(unittest.TestCase):
    def test_groups_in_input_order_and_sorts_lines(self):
        words = [
            {"line": 2, "text": "second", "x0": 5, "y0": 4, "x1": 8, "y1": 7},
            {"line": 1, "text": "hello", "x0": 2, "y0": 3, "x1": 4, "y1": 5},
            {"line": 1, "text": "world", "x0": 1, "y0": 2, "x1": 9, "y1": 8},
            {"line": 2, "text": "line", "x0": 3, "y0": 5, "x1": 10, "y1": 12},
        ]
        self.assertEqual(line_bounds(words), [
            {"line": 1, "text": "hello world", "x0": 1.0, "y0": 2.0, "x1": 9.0, "y1": 8.0},
            {"line": 2, "text": "second line", "x0": 3.0, "y0": 4.0, "x1": 10.0, "y1": 12.0},
        ])

    def test_empty_and_touching_bounds(self):
        self.assertEqual(line_bounds([]), [])
        word = {"line": -1, "text": "", "x0": 2, "y0": 3, "x1": 2, "y1": 3}
        self.assertEqual(line_bounds([word]), [
            {"line": -1, "text": "", "x0": 2.0, "y0": 3.0, "x1": 2.0, "y1": 3.0}
        ])

    def test_accepts_finite_real_coordinates(self):
        word = {"line": 0, "text": "x", "x0": Fraction(1, 2), "y0": 0, "x1": 2.5, "y1": Fraction(3, 1)}
        self.assertEqual(line_bounds([word])[0], {
            "line": 0, "text": "x", "x0": 0.5, "y0": 0.0, "x1": 2.5, "y1": 3.0
        })

    def test_outer_entry_and_key_validation(self):
        for value in (None, (), {}):
            with self.assertRaises(TypeError):
                line_bounds(value)
        with self.assertRaises(TypeError):
            line_bounds([[]])
        valid = {"line": 1, "text": "x", "x0": 0, "y0": 0, "x1": 1, "y1": 1}
        with self.assertRaises(ValueError):
            line_bounds([{**valid, "extra": 1}])
        missing = dict(valid); del missing["text"]
        with self.assertRaises(ValueError):
            line_bounds([missing])

    def test_line_and_text_types(self):
        valid = {"line": 1, "text": "x", "x0": 0, "y0": 0, "x1": 1, "y1": 1}
        for line in (True, 1.0, "1"):
            bad = dict(valid); bad["line"] = line
            with self.assertRaises(TypeError):
                line_bounds([bad])
        for text in (None, 1, True):
            bad = dict(valid); bad["text"] = text
            with self.assertRaises(TypeError):
                line_bounds([bad])

    def test_coordinate_types_and_finiteness(self):
        valid = {"line": 1, "text": "x", "x0": 0, "y0": 0, "x1": 1, "y1": 1}
        for field in ("x0", "y0", "x1", "y1"):
            for value in (True, "0", None, 1 + 0j):
                bad = dict(valid); bad[field] = value
                with self.assertRaises(TypeError):
                    line_bounds([bad])
            for value in (math.inf, -math.inf, math.nan):
                bad = dict(valid); bad[field] = value
                with self.assertRaises(ValueError):
                    line_bounds([bad])

    def test_reversed_bounds_and_non_mutation(self):
        for bad in (
            {"line": 1, "text": "x", "x0": 2, "y0": 0, "x1": 1, "y1": 1},
            {"line": 1, "text": "x", "x0": 0, "y0": 2, "x1": 1, "y1": 1},
        ):
            with self.assertRaises(ValueError):
                line_bounds([bad])
        words = [{"line": 1, "text": "x", "x0": 0, "y0": 0, "x1": 1, "y1": 1}]
        original = [dict(words[0])]
        line_bounds(words)
        self.assertEqual(words, original)


if __name__ == "__main__":
    unittest.main()

